export function reconcileBrokerState(state,broker,at=Date.now()){const changes=[];if(!Array.isArray(broker?.orders))return changes;state.broker_requests=state.broker_requests||{};state.alerts=state.alerts||[];const terminal=new Set(['filled','canceled','expired','rejected','replaced','done_for_day']);for(const request of Object.values(state.broker_requests)){const result=request?.result;if(!result?.broker_order_id)continue;const order=broker.orders.find(o=>o.id===result.broker_order_id||o.client_order_id===result.client_order_id);if(!order||order.status===result.broker_status)continue;const previous=result.broker_status;Object.assign(result,{broker_status:order.status,filled_quantity:number(order.filled_qty)||0,filled_avg_price:number(order.filled_avg_price),filled_at:order.filled_at||null,canceled_at:order.canceled_at||null,rejected_at:order.rejected_at||null});request.status=terminal.has(order.status)?order.status:'submitted';request.updated_at=at;const message='Alpaca Paper '+result.side+' '+result.symbol+' · '+order.status;const alert=state.alerts.find(a=>a.type==='broker_order'&&!a.resolved_at&&a.message.includes(result.symbol));if(alert){alert.message=message;alert.updated_at=at}else state.alerts.unshift({id:crypto.randomUUID(),type:'broker_order',message,at,ref:'VEGA',read:false});changes.push({symbol:result.symbol,previous,status:order.status})}state.alerts=state.alerts.slice(0,500);return changes}
const smartDefaults={risk_per_trade_pct:.5,stop_loss_pct:2,take_profit_pct:4,trailing_stop_pct:1.5,trailing_activation_pct:2,max_crypto_hold_hours:72,max_stock_hold_hours:48,min_consensus_score:100};
