const workingOrder=o=>!['filled','canceled','expired','rejected','replaced','done_for_day'].includes(o.status);
export function recordShadowReview(state,cycle,now=Date.now()){
 state.shadow_reviews=state.shadow_reviews||[];
 for(const review of state.shadow_reviews){
  if(review.outcome||now-review.at<3600000)continue;
  const q=state.markets.find(q=>q.symbol===review.symbol);
  if(!fresh(q,now)||!(q.bid>0))continue;
  if(now-review.at>7200000){review.outcome={status:'missed_window',at:now};continue}
  review.outcome={status:'evaluated',at:now,horizon_minutes:(now-review.at)/60000,exit_bid:q.bid,modeled_return_pct:(q.bid*.999/(review.entry_ask*1.001)-1)*100,assumption:'Observed bid/ask plus 0.1% modeled fee per side; not an actual fill'};
 }
 if(cycle.status!=='shadow'||!cycle.symbol||!(cycle.reference_price>0))return;
 const key=cycle.symbol+':'+cycle.quote_at;
 if(state.shadow_reviews.some(r=>r.key===key||r.symbol===cycle.symbol&&now-r.at<3600000))return;
 state.shadow_reviews.unshift({key,at:now,symbol:cycle.symbol,entry_ask:cycle.reference_price,quote_at:cycle.quote_at,dollars:cycle.risk_sized_ticket,gates:cycle.gates,regime:cycle.regime,origin:'deterministic_rules',executed:false,challenge:['No independent language-model review connected','Quote-sample trend is not a validated trading edge','Spread, fees and changing volatility can erase apparent gains']});
 state.shadow_reviews=state.shadow_reviews.slice(0,200);
}
